def smallest_change(arr):
    def is_palindromic(arr):
        return arr == arr[::-1]

    if is_palindromic(arr):
        return 0

    changes = 0
    left = 0
    right = len(arr) - 1

    while left < right:
        if arr[left] != arr[right]:
            changes += 1
        left += 1
        right -= 1

    return changes

